/* =========================================================
   seed_dump.sql — 카탈로그 재현용 데이터

   사용법:
     ./scripts/reset_db.sh          # Script-2 → Script-3 로 스키마 생성
     docker exec -i codeatlas-postgres psql -U codeatlas -d codeatlas \
         < database/seed_dump.sql

   수록: papers 9 / repositories 12 / paper_repositories 12 / paper_chunks 376 / code_blocks 183 / paper_code_mappings 344
   embedding: 미포함 — 아래 backfill 로 1분이면 채워집니다

   embedding 을 빼고 뜬 이유는 벡터를 텍스트로 적으면 파일의 90%를 차지하는데
   nomic-embed-text 로 금방 복원되기 때문입니다. 반대로 AI 설명(explanation)은
   qwen3:8b 로 100분 넘게 걸리므로 이 파일에 항상 들어 있습니다.

     cd backend && CODEATLAS_EMBEDDING_BACKFILL=true ./mvnw spring-boot:run

   출처·라이선스는 database/seed_manifest.csv 와
   database/THIRD_PARTY_LICENSES.md 를 보세요.
   ========================================================= */

BEGIN;

-- papers (9행)
INSERT INTO papers (id, title, abstract, arxiv_id, doi, pdf_url, source_url, published_date, authors, processing_status, created_at, updated_at) OVERRIDING SYSTEM VALUE VALUES
  ('1', 'Attention Is All You Need', 'The dominant sequence transduction models are based on complex recurrent or convolutional neural networks in an encoder-decoder configuration. The best performing models also connect the encoder and decoder through an attention mechanism. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train. Our model achieves 28.4 BLEU on the WMT 2014 English-to-German translation task, improving over the existing best results, including ensembles by over 2 BLEU. On the WMT 2014 English-to-French translation task, our model establishes a new single-model state-of-the-art BLEU score of 41.8 after training for 3.5 days on eight GPUs, a small fraction of the training costs of the best models from the literature. We show that the Transformer generalizes well to other tasks by applying it successfully to English constituency parsing both with large and limited training data.', '1706.03762', NULL, 'https://arxiv.org/pdf/1706.03762', NULL, '2017-06-12', '[{"name": "Ashish Vaswani"}, {"name": "Noam Shazeer"}, {"name": "Niki Parmar"}, {"name": "Jakob Uszkoreit"}, {"name": "Llion Jones"}, {"name": "Aidan N. Gomez"}, {"name": "Lukasz Kaiser"}, {"name": "Illia Polosukhin"}]', 'COMPLETED', '2026-08-11 17:57:52.018757+00', '2026-08-11 17:57:52.018757+00'),
  ('2', 'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding', 'We introduce a new language representation model called BERT, which stands for Bidirectional Encoder Representations from Transformers. Unlike recent language representation models, BERT is designed to pre-train deep bidirectional representations from unlabeled text by jointly conditioning on both left and right context in all layers. As a result, the pre-trained BERT model can be fine-tuned with just one additional output layer to create state-of-the-art models for a wide range of tasks, such as question answering and language inference, without substantial task-specific architecture modifications. BERT is conceptually simple and empirically powerful. It obtains new state-of-the-art results on eleven natural language processing tasks, including pushing the GLUE score to 80.5% (7.7% point absolute improvement), MultiNLI accuracy to 86.7% (4.6% absolute improvement), SQuAD v1.1 question answering Test F1 to 93.2 (1.5 point absolute improvement) and SQuAD v2.0 Test F1 to 83.1 (5.1 point absolute improvement).', '1810.04805', NULL, 'https://arxiv.org/pdf/1810.04805', NULL, '2018-10-11', '[{"name": "Jacob Devlin"}, {"name": "Ming-Wei Chang"}, {"name": "Kenton Lee"}, {"name": "Kristina Toutanova"}]', 'COMPLETED', '2026-08-11 17:57:52.278562+00', '2026-08-11 17:57:52.278562+00'),
  ('3', 'Learning Transferable Visual Models From Natural Language Supervision', 'State-of-the-art computer vision systems are trained to predict a fixed set of predetermined object categories. This restricted form of supervision limits their generality and usability since additional labeled data is needed to specify any other visual concept. Learning directly from raw text about images is a promising alternative which leverages a much broader source of supervision. We demonstrate that the simple pre-training task of predicting which caption goes with which image is an efficient and scalable way to learn SOTA image representations from scratch on a dataset of 400 million (image, text) pairs collected from the internet. After pre-training, natural language is used to reference learned visual concepts (or describe new ones) enabling zero-shot transfer of the model to downstream tasks. We study the performance of this approach by benchmarking on over 30 different existing computer vision datasets, spanning tasks such as OCR, action recognition in videos, geo-localization, and many types of fine-grained object classification. The model transfers non-trivially to most tasks and is often competitive with a fully supervised baseline without the need for any dataset specific training. For instance, we match the accuracy of the original ResNet-50 on ImageNet zero-shot without needing to use any of the 1.28 million training examples it was trained on. We release our code and pre-trained model weights at https://github.com/OpenAI/CLIP.', '2103.00020', NULL, 'https://arxiv.org/pdf/2103.00020', NULL, '2021-02-26', '[{"name": "Alec Radford"}, {"name": "Jong Wook Kim"}, {"name": "Chris Hallacy"}, {"name": "Aditya Ramesh"}, {"name": "Gabriel Goh"}, {"name": "Sandhini Agarwal"}, {"name": "Girish Sastry"}, {"name": "Amanda Askell"}, {"name": "Pamela Mishkin"}, {"name": "Jack Clark"}, {"name": "Gretchen Krueger"}, {"name": "Ilya Sutskever"}]', 'COMPLETED', '2026-08-11 17:57:52.530604+00', '2026-08-11 17:57:52.530604+00'),
  ('4', 'High-Resolution Image Synthesis with Latent Diffusion Models', 'By decomposing the image formation process into a sequential application of denoising autoencoders, diffusion models (DMs) achieve state-of-the-art synthesis results on image data and beyond. Additionally, their formulation allows for a guiding mechanism to control the image generation process without retraining. However, since these models typically operate directly in pixel space, optimization of powerful DMs often consumes hundreds of GPU days and inference is expensive due to sequential evaluations. To enable DM training on limited computational resources while retaining their quality and flexibility, we apply them in the latent space of powerful pretrained autoencoders. In contrast to previous work, training diffusion models on such a representation allows for the first time to reach a near-optimal point between complexity reduction and detail preservation, greatly boosting visual fidelity. By introducing cross-attention layers into the model architecture, we turn diffusion models into powerful and flexible generators for general conditioning inputs such as text or bounding boxes and high-resolution synthesis becomes possible in a convolutional manner. Our latent diffusion models (LDMs) achieve a new state of the art for image inpainting and highly competitive performance on various tasks, including unconditional image generation, semantic scene synthesis, and super-resolution, while significantly reducing computational requirements compared to pixel-based DMs. Code is available at https://github.com/CompVis/latent-diffusion .', '2112.10752', NULL, 'https://arxiv.org/pdf/2112.10752', NULL, '2021-12-20', '[{"name": "Robin Rombach"}, {"name": "Andreas Blattmann"}, {"name": "Dominik Lorenz"}, {"name": "Patrick Esser"}, {"name": "Björn Ommer"}]', 'COMPLETED', '2026-08-11 17:57:52.771656+00', '2026-08-11 17:57:52.771656+00'),
  ('5', 'The Llama 3 Herd of Models', 'Modern artificial intelligence (AI) systems are powered by foundation models. This paper presents a new set of foundation models, called Llama 3. It is a herd of language models that natively support multilinguality, coding, reasoning, and tool usage. Our largest model is a dense Transformer with 405B parameters and a context window of up to 128K tokens. This paper presents an extensive empirical evaluation of Llama 3. We find that Llama 3 delivers comparable quality to leading language models such as GPT-4 on a plethora of tasks. We publicly release Llama 3, including pre-trained and post-trained versions of the 405B parameter language model and our Llama Guard 3 model for input and output safety. The paper also presents the results of experiments in which we integrate image, video, and speech capabilities into Llama 3 via a compositional approach. We observe this approach performs competitively with the state-of-the-art on image, video, and speech recognition tasks. The resulting models are not yet being broadly released as they are still under development.', '2407.21783', NULL, 'https://arxiv.org/pdf/2407.21783', NULL, '2024-07-31', '[{"name": "Aaron Grattafiori"}, {"name": "Abhimanyu Dubey"}, {"name": "Abhinav Jauhri"}, {"name": "Abhinav Pandey"}, {"name": "Abhishek Kadian"}, {"name": "Ahmad Al-Dahle"}, {"name": "Aiesha Letman"}, {"name": "Akhil Mathur"}, {"name": "Alan Schelten"}, {"name": "Alex Vaughan"}, {"name": "Amy Yang"}, {"name": "Angela Fan"}]', 'COMPLETED', '2026-08-11 17:57:53.032405+00', '2026-08-11 17:57:53.032405+00'),
  ('6', 'Deep Residual Learning for Image Recognition', 'Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper than those used previously. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs, instead of learning unreferenced functions. We provide comprehensive empirical evidence showing that these residual networks are easier to optimize, and can gain accuracy from considerably increased depth. On the ImageNet dataset we evaluate residual nets with a depth of up to 152 layers---8x deeper than VGG nets but still having lower complexity. An ensemble of these residual nets achieves 3.57% error on the ImageNet test set. This result won the 1st place on the ILSVRC 2015 classification task. We also present analysis on CIFAR-10 with 100 and 1000 layers. The depth of representations is of central importance for many visual recognition tasks. Solely due to our extremely deep representations, we obtain a 28% relative improvement on the COCO object detection dataset. Deep residual nets are foundations of our submissions to ILSVRC & COCO 2015 competitions, where we also won the 1st places on the tasks of ImageNet detection, ImageNet localization, COCO detection, and COCO segmentation.', '1512.03385', NULL, 'https://arxiv.org/pdf/1512.03385', NULL, '2015-12-10', '[{"name": "Kaiming He"}, {"name": "Xiangyu Zhang"}, {"name": "Shaoqing Ren"}, {"name": "Jian Sun"}]', 'COMPLETED', '2026-08-11 17:57:53.282277+00', '2026-08-11 17:57:53.282277+00'),
  ('7', 'Segment Anything', 'We introduce the Segment Anything (SA) project: a new task, model, and dataset for image segmentation. Using our efficient model in a data collection loop, we built the largest segmentation dataset to date (by far), with over 1 billion masks on 11M licensed and privacy respecting images. The model is designed and trained to be promptable, so it can transfer zero-shot to new image distributions and tasks. We evaluate its capabilities on numerous tasks and find that its zero-shot performance is impressive -- often competitive with or even superior to prior fully supervised results. We are releasing the Segment Anything Model (SAM) and corresponding dataset (SA-1B) of 1B masks and 11M images at https://segment-anything.com to foster research into foundation models for computer vision.', '2304.02643', NULL, 'https://arxiv.org/pdf/2304.02643', NULL, '2023-04-05', '[{"name": "Alexander Kirillov"}, {"name": "Eric Mintun"}, {"name": "Nikhila Ravi"}, {"name": "Hanzi Mao"}, {"name": "Chloe Rolland"}, {"name": "Laura Gustafson"}, {"name": "Tete Xiao"}, {"name": "Spencer Whitehead"}, {"name": "Alexander C. Berg"}, {"name": "Wan-Yen Lo"}, {"name": "Piotr Dollár"}, {"name": "Ross Girshick"}]', 'COMPLETED', '2026-08-11 17:57:53.557073+00', '2026-08-11 17:57:53.557073+00'),
  ('8', 'An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale', 'While the Transformer architecture has become the de-facto standard for natural language processing tasks, its applications to computer vision remain limited. In vision, attention is either applied in conjunction with convolutional networks, or used to replace certain components of convolutional networks while keeping their overall structure in place. We show that this reliance on CNNs is not necessary and a pure transformer applied directly to sequences of image patches can perform very well on image classification tasks. When pre-trained on large amounts of data and transferred to multiple mid-sized or small image recognition benchmarks (ImageNet, CIFAR-100, VTAB, etc.), Vision Transformer (ViT) attains excellent results compared to state-of-the-art convolutional networks while requiring substantially fewer computational resources to train.', '2010.11929', NULL, 'https://arxiv.org/pdf/2010.11929', NULL, '2020-10-22', '[{"name": "Alexey Dosovitskiy"}, {"name": "Lucas Beyer"}, {"name": "Alexander Kolesnikov"}, {"name": "Dirk Weissenborn"}, {"name": "Xiaohua Zhai"}, {"name": "Thomas Unterthiner"}, {"name": "Mostafa Dehghani"}, {"name": "Matthias Minderer"}, {"name": "Georg Heigold"}, {"name": "Sylvain Gelly"}, {"name": "Jakob Uszkoreit"}, {"name": "Neil Houlsby"}]', 'COMPLETED', '2026-08-11 17:57:53.80428+00', '2026-08-11 17:57:53.80428+00'),
  ('9', 'You Only Look Once: Unified, Real-Time Object Detection', 'We present YOLO, a new approach to object detection. Prior work on object detection repurposes classifiers to perform detection. Instead, we frame object detection as a regression problem to spatially separated bounding boxes and associated class probabilities. A single neural network predicts bounding boxes and class probabilities directly from full images in one evaluation. Since the whole detection pipeline is a single network, it can be optimized end-to-end directly on detection performance. Our unified architecture is extremely fast. Our base YOLO model processes images in real-time at 45 frames per second. A smaller version of the network, Fast YOLO, processes an astounding 155 frames per second while still achieving double the mAP of other real-time detectors. Compared to state-of-the-art detection systems, YOLO makes more localization errors but is far less likely to predict false detections where nothing exists. Finally, YOLO learns very general representations of objects. It outperforms all other detection methods, including DPM and R-CNN, by a wide margin when generalizing from natural images to artwork on both the Picasso Dataset and the People-Art Dataset.', '1506.02640', NULL, 'https://arxiv.org/pdf/1506.02640', NULL, '2015-06-08', '[{"name": "Joseph Redmon"}, {"name": "Santosh Divvala"}, {"name": "Ross Girshick"}, {"name": "Ali Farhadi"}]', 'COMPLETED', '2026-08-11 17:57:54.042293+00', '2026-08-11 17:57:54.042293+00');

