  ('1', '1', 'transformer/Models.py', 'get_pad_mask', 'FUNCTION', 'Python', '11', '12', 'def get_pad_mask(seq, pad_idx):,
      return (seq != pad_idx).unsqueeze(-2)', NULL, '2026-08-11 17:57:52.018757+00'),
  ('2', '1', 'transformer/Models.py', 'get_subsequent_mask', 'FUNCTION', 'Python', '15', '20', 'def get_subsequent_mask(seq):,
      '''''' For masking out the subsequent info. '''''',
      sz_b, len_s = seq.size(),
      subsequent_mask = (1 - torch.triu(,
          torch.ones((1, len_s, len_s), device=seq.device), diagonal=1)).bool(),
      return subsequent_mask', NULL, '2026-08-11 17:57:52.018757+00'),
  ('3', '1', 'transformer/Models.py', '__init__', 'METHOD', 'Python', '25', '29', '    def __init__(self, d_hid, n_position=200):,
          super(PositionalEncoding, self).__init__(),
          # Not a parameter,
          self.register_buffer(''pos_table'', self._get_sinusoid_encoding_table(n_position, d_hid))', 'PositionalEncoding', '2026-08-11 17:57:52.018757+00'),
  ('4', '1', 'transformer/Models.py', '_get_sinusoid_encoding_table', 'METHOD', 'Python', '31', '42', '    def _get_sinusoid_encoding_table(self, n_position, d_hid):,
          '''''' Sinusoid position encoding table '''''',
          # TODO: make it with torch instead of numpy,
          def get_position_angle_vec(position):,
              return [position / np.power(10000, 2 * (hid_j // 2) / d_hid) for hid_j in range(d_hid)],
          sinusoid_table = np.array([get_position_angle_vec(pos_i) for pos_i in range(n_position)]),
          sinusoid_table[:, 0::2] = np.sin(sinusoid_table[:, 0::2])  # dim 2i,
          sinusoid_table[:, 1::2] = np.cos(sinusoid_table[:, 1::2])  # dim 2i+1,
          return torch.FloatTensor(sinusoid_table).unsqueeze(0)', 'PositionalEncoding', '2026-08-11 17:57:52.018757+00'),
  ('5', '1', 'transformer/Models.py', 'forward', 'METHOD', 'Python', '44', '45', '    def forward(self, x):,
          return x + self.pos_table[:, :x.size(1)].clone().detach()', 'PositionalEncoding', '2026-08-11 17:57:52.018757+00'),
  ('6', '1', 'transformer/Models.py', '__init__', 'METHOD', 'Python', '51', '65', '    def __init__(,
              self, n_src_vocab, d_word_vec, n_layers, n_head, d_k, d_v,,
              d_model, d_inner, pad_idx, dropout=0.1, n_position=200, scale_emb=False):,
          super().__init__(),
          self.src_word_emb = nn.Embedding(n_src_vocab, d_word_vec, padding_idx=pad_idx),
          self.position_enc = PositionalEncoding(d_word_vec, n_position=n_position),
          self.dropout = nn.Dropout(p=dropout),
          self.layer_stack = nn.ModuleList([,
              EncoderLayer(d_model, d_inner, n_head, d_k, d_v, dropout=dropout),
              for _ in range(n_layers)]),
          self.layer_norm = nn.LayerNorm(d_model, eps=1e-6),
          self.scale_emb = scale_emb,
          self.d_model = d_model', 'Encoder', '2026-08-11 17:57:52.018757+00'),
  ('7', '1', 'transformer/Models.py', 'forward', 'METHOD', 'Python', '67', '84', '    def forward(self, src_seq, src_mask, return_attns=False):,
          enc_slf_attn_list = [],
          # -- Forward,
          enc_output = self.src_word_emb(src_seq),
          if self.scale_emb:,
              enc_output *= self.d_model ** 0.5,
          enc_output = self.dropout(self.position_enc(enc_output)),
          enc_output = self.layer_norm(enc_output),
          for enc_layer in self.layer_stack:,
              enc_output, enc_slf_attn = enc_layer(enc_output, slf_attn_mask=src_mask),
              enc_slf_attn_list += [enc_slf_attn] if return_attns else [],
          if return_attns:,
              return enc_output, enc_slf_attn_list,
          return enc_output,', 'Encoder', '2026-08-11 17:57:52.018757+00'),
  ('8', '1', 'transformer/Models.py', '__init__', 'METHOD', 'Python', '90', '104', '    def __init__(,
              self, n_trg_vocab, d_word_vec, n_layers, n_head, d_k, d_v,,
              d_model, d_inner, pad_idx, n_position=200, dropout=0.1, scale_emb=False):,
          super().__init__(),
          self.trg_word_emb = nn.Embedding(n_trg_vocab, d_word_vec, padding_idx=pad_idx),
          self.position_enc = PositionalEncoding(d_word_vec, n_position=n_position),
          self.dropout = nn.Dropout(p=dropout),
          self.layer_stack = nn.ModuleList([,
              DecoderLayer(d_model, d_inner, n_head, d_k, d_v, dropout=dropout),
              for _ in range(n_layers)]),
          self.layer_norm = nn.LayerNorm(d_model, eps=1e-6),
          self.scale_emb = scale_emb,
          self.d_model = d_model', 'Decoder', '2026-08-11 17:57:52.018757+00'),
  ('9', '1', 'transformer/Models.py', 'forward', 'METHOD', 'Python', '106', '125', '    def forward(self, trg_seq, trg_mask, enc_output, src_mask, return_attns=False):,
          dec_slf_attn_list, dec_enc_attn_list = [], [],
          # -- Forward,
          dec_output = self.trg_word_emb(trg_seq),
          if self.scale_emb:,
              dec_output *= self.d_model ** 0.5,
          dec_output = self.dropout(self.position_enc(dec_output)),
          dec_output = self.layer_norm(dec_output),
          for dec_layer in self.layer_stack:,
              dec_output, dec_slf_attn, dec_enc_attn = dec_layer(,
                  dec_output, enc_output, slf_attn_mask=trg_mask, dec_enc_attn_mask=src_mask),
              dec_slf_attn_list += [dec_slf_attn] if return_attns else [],
              dec_enc_attn_list += [dec_enc_attn] if return_attns else [],
          if return_attns:,
              return dec_output, dec_slf_attn_list, dec_enc_attn_list,
          return dec_output,', 'Decoder', '2026-08-11 17:57:52.018757+00'),
