  ('134', '9', 'segment_anything/modeling/image_encoder.py', 'PatchEmbed', 'CLASS', 'Python', '364', '395', 'class PatchEmbed(nn.Module):,
      """,
      Image to Patch Embedding.,
      """,
      def __init__(,
          self,,
          kernel_size: Tuple[int, int] = (16, 16),,
          stride: Tuple[int, int] = (16, 16),,
          padding: Tuple[int, int] = (0, 0),,
          in_chans: int = 3,,
          embed_dim: int = 768,,
      ) -> None:,
          """,
          Args:,
              kernel_size (Tuple): kernel size of the projection layer.,
              stride (Tuple): stride of the projection layer.,
              padding (Tuple): padding size of the projection layer.,
              in_chans (int): Number of input image channels.,
              embed_dim (int): Patch embedding dimension.,
          """,
          super().__init__(),
          self.proj = nn.Conv2d(,
              in_chans, embed_dim, kernel_size=kernel_size, stride=stride, padding=padding,
          ),
      def forward(self, x: torch.Tensor) -> torch.Tensor:,
          x = self.proj(x),
          # B C H W -> B H W C,
          x = x.permute(0, 2, 3, 1),
          return x', NULL, '2026-08-11 17:57:53.557073+00'),
  ('135', '9', 'segment_anything/modeling/image_encoder.py', 'Block', 'CLASS', 'Python', '119', '182', 'class Block(nn.Module):,
      """Transformer blocks with support of window attention and residual propagation blocks""",
      def __init__(,
          self,,
          dim: int,,
          num_heads: int,,
          mlp_ratio: float = 4.0,,
          qkv_bias: bool = True,,
          norm_layer: Type[nn.Module] = nn.LayerNorm,,
          act_layer: Type[nn.Module] = nn.GELU,,
          use_rel_pos: bool = False,,
          rel_pos_zero_init: bool = True,,
          window_size: int = 0,,
          input_size: Optional[Tuple[int, int]] = None,,
      ) -> None:,
          """,
          Args:,
              dim (int): Number of input channels.,
              num_heads (int): Number of attention heads in each ViT block.,
              mlp_ratio (float): Ratio of mlp hidden dim to embedding dim.,
              qkv_bias (bool): If True, add a learnable bias to query, key, value.,
              norm_layer (nn.Module): Normalization layer.,
              act_layer (nn.Module): Activation layer.,
              use_rel_pos (bool): If True, add relative positional embeddings to the attention map.,
              rel_pos_zero_init (bool): If True, zero initialize relative positional parameters.,
              window_size (int): Window size for window attention blocks. If it equals 0, then,
                  use global attention.,
              input_size (tuple(int, int) or None): Input resolution for calculating the relative,
                  positional parameter size.,
          """,
          super().__init__(),
          self.norm1 = norm_layer(dim),
          self.attn = Attention(,
              dim,,
              num_heads=num_heads,,
              qkv_bias=qkv_bias,,
              use_rel_pos=use_rel_pos,,
              rel_pos_zero_init=rel_pos_zero_init,,
              input_size=input_size if window_size == 0 else (window_size, window_size),,
          ),
          self.norm2 = norm_layer(dim),
          self.mlp = MLPBlock(embedding_dim=dim, mlp_dim=int(dim * mlp_ratio), act=act_layer),
          self.window_size = window_size,
      def forward(self, x: torch.Tensor) -> torch.Tensor:,
          shortcut = x,
          x = self.norm1(x),
          # Window partition,
          if self.window_size > 0:,
              H, W = x.shape[1], x.shape[2],
              x, pad_hw = window_partition(x, self.window_size),
          x = self.attn(x),
          # Reverse window partition,
          if self.window_size > 0:,
              x = window_unpartition(x, self.window_size, pad_hw, (H, W)),
          x = shortcut + x,
          x = x + self.mlp(self.norm2(x)),
