  ('141', '9', 'segment_anything/modeling/transformer.py', 'TwoWayAttentionBlock', 'CLASS', 'Python', '109', '182', 'class TwoWayAttentionBlock(nn.Module):,
      def __init__(,
          self,,
          embedding_dim: int,,
          num_heads: int,,
