  ('167', '12', 'examples/detector.c', 'test_detector', 'FUNCTION', 'C', '562', '621', E'void test_detector(char *datacfg, char *cfgfile, char *weightfile, char *filename, float thresh, float hier_thresh, char *outfile, int fullscreen),
  {,
      list *options = read_data_cfg(datacfg);,
      char *name_list = option_find_str(options, "names", "data/names.list");,
      char **names = get_labels(name_list);,
