      },
      return 0;,
  }', NULL, '2026-08-11 17:57:54.042293+00'),
  ('178', '12', 'src/network.c', 'forward_network', 'FUNCTION', 'C', '188', '211', 'void forward_network(network *netp),
  {,
  #ifdef GPU,
      if(netp->gpu_index >= 0){,
          forward_network_gpu(netp);   ,
          return;,
      },
  #endif,
      network net = *netp;,
      int i;,
      for(i = 0; i < net.n; ++i){,
          net.index = i;,
          layer l = net.layers[i];,
          if(l.delta){,
              fill_cpu(l.outputs * l.batch, 0, l.delta, 1);,
          },
          l.forward(l, net);,
          net.input = l.output;,
          if(l.truth) {,
              net.truth = l.output;,
          },
      },
      calc_network_cost(netp);,
  }', NULL, '2026-08-11 17:57:54.042293+00'),
  ('179', '12', 'src/box.c', 'do_nms_sort', 'FUNCTION', 'C', '58', '89', 'void do_nms_sort(detection *dets, int total, int classes, float thresh),
  {,
      int i, j, k;,
      k = total-1;,
      for(i = 0; i <= k; ++i){,
          if(dets[i].objectness == 0){,
              detection swap = dets[i];,
              dets[i] = dets[k];,
              dets[k] = swap;,
              --k;,
              --i;,
          },
      },
      total = k+1;,
      for(k = 0; k < classes; ++k){,
          for(i = 0; i < total; ++i){,
              dets[i].sort_class = k;,
          },
          qsort(dets, total, sizeof(detection), nms_comparator);,
          for(i = 0; i < total; ++i){,
              if(dets[i].prob[k] == 0) continue;,
              box a = dets[i].bbox;,
              for(j = i+1; j < total; ++j){,
                  box b = dets[j].bbox;,
                  if (box_iou(a, b) > thresh){,
                      dets[j].prob[k] = 0;,
                  },
              },
          },
      },
  }', NULL, '2026-08-11 17:57:54.042293+00'),
  ('180', '12', 'src/network.c', 'train_network', 'FUNCTION', 'C', '314', '328', 'float train_network(network *net, data d),
  {,
      assert(d.X.rows % net->batch == 0);,
      int batch = net->batch;,
      int n = d.X.rows / batch;,
      int i;,
      float sum = 0;,
      for(i = 0; i < n; ++i){,
          get_next_batch(d, batch, i*batch, net->input, net->truth);,
          float err = train_network_datum(net);,
          sum += err;,
      },
      return (float)sum/(n*batch);,
  }', NULL, '2026-08-11 17:57:54.042293+00'),
